package com.econest.view;
import com.econest.model.DeliveryAgent;
import javax.swing.*;import java.awt.*;import java.awt.event.ActionListener;import java.util.List;
public class DeliveryAgentPanel extends JPanel{
 private final JTextField name=new JTextField(14),phone=new JTextField(12),email=new JTextField(16),address=new JTextField(18),vehicleNo=new JTextField(12);
 private final JComboBox<String> vehicleType=new JComboBox<>(new String[]{"Motorcycle","Car","Van","Truck"});
 private final JComboBox<String> status=new JComboBox<>(new String[]{"Available","Unavailable"});
 private final JButton add=UiUtils.button("Add",UiUtils.PRIMARY),update=UiUtils.button("Update",UiUtils.PRIMARY),del=UiUtils.button("Delete",UiUtils.DANGER),clear=UiUtils.button("Clear",UiUtils.NEUTRAL),search=UiUtils.button("Search",UiUtils.NEUTRAL),all=UiUtils.button("Show All",UiUtils.NEUTRAL);
 private final JTextField searchField=new JTextField(18); private final DeliveryAgentTableModel model=new DeliveryAgentTableModel(); private final JTable table=new JTable(model);
 public DeliveryAgentPanel(){setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(10,10,10,10));add(form(),BorderLayout.NORTH);add(tablePanel(),BorderLayout.CENTER);}
 private JPanel form(){JPanel f=new JPanel(new GridBagLayout());f.setBorder(BorderFactory.createTitledBorder("Delivery Agent Details"));Object[][] x={{"Name",name,"Phone",phone},{"Email",email,"Address",address},{"Vehicle Type",vehicleType,"Vehicle Number",vehicleNo},{"Status",status}};for(int r=0;r<x.length;r++)for(int c=0;c<x[r].length;c+=2){place(f,new JLabel((String)x[r][c]),c,r);place(f,(Component)x[r][c+1],c+1,r);}JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(add);b.add(update);b.add(del);b.add(clear);JPanel w=new JPanel(new BorderLayout());w.add(f,BorderLayout.CENTER);w.add(b,BorderLayout.SOUTH);return w;}
 private JPanel tablePanel(){JPanel s=new JPanel(new FlowLayout(FlowLayout.LEFT));s.add(new JLabel("Search:"));s.add(searchField);s.add(search);s.add(all);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setRowHeight(24);JPanel p=new JPanel(new BorderLayout());p.add(s,BorderLayout.NORTH);p.add(new JScrollPane(table),BorderLayout.CENTER);return p;}
 private void place(JPanel p,Component c,int x,int y){GridBagConstraints g=new GridBagConstraints();g.gridx=x;g.gridy=y;g.insets=new Insets(4,6,4,6);g.anchor=GridBagConstraints.WEST;p.add(c,g);}
 public String getNameInput(){return name.getText();}public String getPhoneInput(){return phone.getText();}public String getEmailInput(){return email.getText();}public String getAddressInput(){return address.getText();}public String getVehicleType(){return(String)vehicleType.getSelectedItem();}public String getVehicleNumber(){return vehicleNo.getText();}public String getStatus(){return(String)status.getSelectedItem();}public String getSearchText(){return searchField.getText();}
 public DeliveryAgent getSelectedAgent(){int r=table.getSelectedRow();return r<0?null:model.getAgentAt(r);} public void setAgents(List<DeliveryAgent>x){model.setAgents(x);}
 public void populateForm(DeliveryAgent a){name.setText(a.getName());phone.setText(a.getPhone());email.setText(a.getEmail());address.setText(a.getAddress());vehicleType.setSelectedItem(a.getVehicleType());vehicleNo.setText(a.getVehicleNumber());status.setSelectedItem(a.getStatus());}
 public void clearForm(){name.setText("");phone.setText("");email.setText("");address.setText("");vehicleNo.setText("");status.setSelectedIndex(0);table.clearSelection();}
 public void onAdd(ActionListener l){add.addActionListener(l);}public void onUpdate(ActionListener l){update.addActionListener(l);}public void onDelete(ActionListener l){del.addActionListener(l);}public void onClear(ActionListener l){clear.addActionListener(l);}public void onSearch(ActionListener l){search.addActionListener(l);searchField.addActionListener(l);}public void onShowAll(ActionListener l){all.addActionListener(l);}public void onRowSelected(Runnable r){table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting())r.run();});}
 public void showMessage(String m){JOptionPane.showMessageDialog(this,m,"EcoNest",JOptionPane.INFORMATION_MESSAGE);}public void showError(String m){JOptionPane.showMessageDialog(this,m,"Error",JOptionPane.ERROR_MESSAGE);}public boolean confirm(String m){return JOptionPane.showConfirmDialog(this,m,"Please confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
}
